INSERT INTO dsl_rolling_diag_2a7d2bb431c5.tail_2 SELECT mktcode,tgtcode,bizdate,closePrice,highPrice,lowPrice FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,b.closePrice,b.highPrice,b.lowPrice,ROW_NUMBER() OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate DESC) AS rn FROM (SELECT mktcode,tgtcode,bizdate,closePrice,highPrice,lowPrice FROM dsl_rolling_diag_2a7d2bb431c5.tail_1 UNION ALL SELECT b.mktcode,b.tgtcode,b.bizdate,b.closePrice,b.highPrice,b.lowPrice FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate>'2026-04-13' AND b.bizdate<='2026-04-14') b WHERE b.bizdate<='2026-04-14') t WHERE rn<=249;
